import { useState, useEffect, useRef } from "react";

const SALA_IMG = "data:image/jpeg;base64,";
const ADMIN_PIN = "2607";
const SLOTS = Array.from({length: 14}, (_, i) => i + 8);
const DAYS_ES = ["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"];
const MONTHS_ES = ["Ene","Feb","Mar","Abr","May","Jun","Jul","Ago","Sep","Oct","Nov","Dic"];

function getMonday(d) {
  const dt = new Date(d); dt.setHours(0,0,0,0);
  const wd = dt.getDay();
  dt.setDate(dt.getDate() - (wd === 0 ? 6 : wd - 1));
  return dt;
}
function addDays(d, n) { const dt = new Date(d); dt.setDate(dt.getDate() + n); return dt; }
function fmtDate(d) { return d.toISOString().slice(0,10); }
function cid(date, hour) { return `${fmtDate(date)}_${hour}`; }
function dayIdx(d) { return d.getDay() === 0 ? 6 : d.getDay() - 1; }

export default function App() {
  const todayBase = () => { const d = new Date(); d.setHours(0,0,0,0); return d; };
  const [weekStart, setWeekStart] = useState(() => getMonday(new Date()));
  const [weekOff, setWeekOff] = useState(0);
  const [bookings, setBookings] = useState({});
  const [sel, setSel] = useState(new Set());
  const [drag, setDrag] = useState(false);
  const [showBook, setShowBook] = useState(false);
  const [showAdmin, setShowAdmin] = useState(false);
  const [showDel, setShowDel] = useState(false);
  const [delKey, setDelKey] = useState(null);
  const [bandName, setBandName] = useState("");
  const [pin, setPin] = useState("");
  const [pinErr, setPinErr] = useState(false);
  const [admin, setAdmin] = useState(false);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    (async () => {
      try { const r = await window.storage.get("sc_bookings_v3"); if (r?.value) setBookings(JSON.parse(r.value)); } catch {}
      setLoaded(true);
    })();
  }, []);

  const save = async (b) => { try { await window.storage.set("sc_bookings_v3", JSON.stringify(b)); } catch {} };

  const today = todayBase();
  const allDays = Array.from({length: 7}, (_, i) => addDays(weekStart, i));
  const visibleDays = allDays.filter(d => { const dc = new Date(d); dc.setHours(0,0,0,0); return dc >= today; });
  const isToday = (d) => fmtDate(d) === fmtDate(today);
  const isPast = (date, hour) => { const c = new Date(date); c.setHours(hour,0,0,0); return c < new Date(); };
  const canSel = (date, hour) => !isPast(date, hour) && !bookings[cid(date, hour)];
  const isCurrentWeek = getMonday(today).getTime() === weekStart.getTime();

  const prevWeek = () => {
    if (isCurrentWeek) return;
    const p = addDays(weekStart, -7); setWeekStart(getMonday(p)); setWeekOff(o => o-1); setSel(new Set());
  };
  const nextWeek = () => { setWeekStart(addDays(weekStart, 7)); setWeekOff(o => o+1); setSel(new Set()); };

  const onMouseDown = (date, hour, e) => {
    e.preventDefault();
    const key = cid(date, hour);
    if (admin && bookings[key]) { setDelKey(key); setShowDel(true); return; }
    if (!canSel(date, hour)) return;
    setDrag(true); setSel(new Set([key]));
  };
  const onMouseEnter = (date, hour) => {
    if (!drag || !canSel(date, hour)) return;
    setSel(prev => new Set([...prev, cid(date, hour)]));
  };
  const onMouseUp = () => { if (drag) { setDrag(false); if (sel.size > 0) setShowBook(true); } };

  const onTouchStart = (date, hour, e) => {
    const key = cid(date, hour);
    if (admin && bookings[key]) { e.preventDefault(); setDelKey(key); setShowDel(true); return; }
    if (!canSel(date, hour)) return;
    e.preventDefault(); setDrag(true); setSel(new Set([key]));
  };
  const onTouchMove = (e) => {
    if (!drag) return; e.preventDefault();
    const t = e.touches[0]; const el = document.elementFromPoint(t.clientX, t.clientY);
    const key = el?.dataset?.cid;
    if (key) { const [ds, hs] = key.split('_'); if (!bookings[key] && !isPast(new Date(ds+'T00:00:00'), parseInt(hs))) setSel(prev => new Set([...prev, key])); }
  };
  const onTouchEnd = () => { if (drag) { setDrag(false); if (sel.size > 0) setShowBook(true); } };

  const confirmBook = async () => {
    if (!bandName.trim()) return;
    const b = {...bookings};
    sel.forEach(key => { b[key] = { name: bandName.trim(), ts: Date.now() }; });
    setBookings(b); await save(b); setSel(new Set()); setBandName(""); setShowBook(false);
  };
  const confirmDel = async () => {
    const b = {...bookings}; delete b[delKey];
    setBookings(b); await save(b); setDelKey(null); setShowDel(false);
  };
  const loginAdmin = () => {
    if (pin === ADMIN_PIN) { setAdmin(true); setShowAdmin(false); setPin(""); setPinErr(false); }
    else setPinErr(true);
  };

  const weekLabel = () => {
    const end = addDays(weekStart, 6);
    const sm = weekStart.getMonth(), em = end.getMonth(), sy = weekStart.getFullYear(), ey = end.getFullYear();
    if (sm === em) return `${weekStart.getDate()} – ${end.getDate()} ${MONTHS_ES[em]} ${ey}`;
    return `${weekStart.getDate()} ${MONTHS_ES[sm]}${sy!==ey?' '+sy:''} – ${end.getDate()} ${MONTHS_ES[em]} ${ey}`;
  };

  const selHours = () => [...sel].map(k => parseInt(k.split('_')[1])).sort((a,b)=>a-b);
  const selDayStrs = () => [...new Set([...sel].map(k => k.split('_')[0]))];
  const selLabel = () => {
    if (!sel.size) return "";
    const h = selHours(); const minH = h[0], maxH = h[h.length-1];
    const days2 = selDayStrs().map(ds => { const d = new Date(ds+'T00:00:00'); return `${DAYS_ES[dayIdx(d)]} ${d.getDate()}`; }).join(", ");
    const totalH = maxH - minH + 1;
    if (h.length === 1) return `${days2} · ${minH}:00 – ${minH+1}:00 (1h)`;
    return `${days2} · ${minH}:00 – ${maxH+1}:00 (${totalH}h)`;
  };
  const priceStr = () => {
    const h = selHours();
    const n = new Set(h).size;
    if (n <= 1) return "~$10.000 · 1hs";
    if (n === 2) return "$20.000 · 2hs";
    if (n === 3) return "🔥 $25.000 · Promo 3hs";
    return `$${n*10000} · ${n}hs`;
  };

  const bgPan = Math.max(-70, Math.min(70, weekOff * 18));
  const S = styles;

  return (
    <div style={S.root} onMouseUp={onMouseUp} onTouchMove={onTouchMove} onTouchEnd={onTouchEnd}>
      {/* Background */}
      <div style={S.bgWrap}>
        <div style={{...S.bgInner, transform:`translateX(${bgPan}px)`, transition:'transform 0.8s cubic-bezier(.25,.46,.45,.94)'}}>
          <img src={SALA_IMG} alt="" style={S.bgImg} />
          <div style={S.bgOverlay} />
        </div>
      </div>

      {/* Header */}
      <header style={S.header}>
        <div>
          <div style={S.logoText}>STRATOCASTLE</div>
          <div style={S.logoSub}>🎸 sala de ensayo · San Luis</div>
        </div>
        <div style={{display:'flex',gap:8,alignItems:'center'}}>
          {admin
            ? <button style={{...S.adminBtn,...S.adminOn}} onClick={() => setAdmin(false)}>🔓 Admin</button>
            : <button style={S.adminBtn} onClick={() => setShowAdmin(true)}>🔒</button>
          }
        </div>
      </header>

      {/* Week nav */}
      <div style={S.weekNav}>
        <button style={{...S.navBtn, opacity: isCurrentWeek ? 0.3 : 1}} onClick={prevWeek} disabled={isCurrentWeek}>‹</button>
        <span style={S.weekLabel}>{weekLabel()}</span>
        <button style={S.navBtn} onClick={nextWeek}>›</button>
      </div>

      {admin && <div style={S.adminBanner}>MODO ADMIN · Tocá un turno para eliminarlo</div>}

      {/* Grid */}
      {!loaded
        ? <div style={S.loader}>Cargando…</div>
        : visibleDays.length === 0
          ? <div style={S.loader}>No quedan días esta semana.<br/><button style={{...S.navBtn,marginTop:14}} onClick={nextWeek}>Próxima semana →</button></div>
          : (
        <div style={S.gridWrap}>
          <div style={{...S.grid, gridTemplateColumns:`58px repeat(${visibleDays.length},1fr)`}}>
            <div style={S.thEmpty}/>
            {visibleDays.map(day => (
              <div key={fmtDate(day)} style={{...S.th,...(isToday(day)?S.thToday:{})}}>
                <span style={S.thDay}>{DAYS_ES[dayIdx(day)]}</span>
                <span style={S.thNum}>{day.getDate()}</span>
                {isToday(day) && <span style={S.todayDot}/>}
              </div>
            ))}

            {SLOTS.map(hour => (
              <>{/* key on fragment not supported, use React.Fragment */}
                <React.Fragment key={`row-${hour}`}>
                <div style={S.timeCell}>{hour}:00</div>
                {visibleDays.map(day => {
                  const key = cid(day, hour);
                  const booked = bookings[key];
                  const past = isPast(day, hour);
                  const inSel = sel.has(key);
                  const cs = {
                    ...S.cell,
                    ...(past ? S.cellPast : booked ? S.cellBooked : inSel ? S.cellSel : S.cellFree),
                    ...(isToday(day) ? {borderLeftColor:'rgba(201,184,138,.45)', borderLeftWidth:2} : {})
                  };
                  return (
                    <div key={key} data-cid={key} style={cs}
                      onMouseDown={e => onMouseDown(day, hour, e)}
                      onMouseEnter={() => onMouseEnter(day, hour)}
                      onTouchStart={e => onTouchStart(day, hour, e)}>
                      {booked && (
                        <span style={S.cellTxt}>
                          {booked.name}{admin&&<span style={{color:'#FF8080',marginLeft:3}}>✕</span>}
                        </span>
                      )}
                      {inSel && !booked && <span style={S.selDot}/>}
                    </div>
                  );
                })}
                </React.Fragment>
              </>
            ))}
          </div>
        </div>
      )}

      {/* Selection bar */}
      {sel.size > 0 && !showBook && (
        <div style={S.selBar}>
          <div style={{flex:1}}>
            <div style={S.selLabelTxt}>{selLabel()}</div>
            <div style={S.selPriceTxt}>{priceStr()}</div>
          </div>
          <button style={S.btnReservar} onClick={() => setShowBook(true)}>RESERVAR →</button>
          <button style={S.btnClear} onClick={() => setSel(new Set())}>✕</button>
        </div>
      )}

      {/* Booking modal */}
      {showBook && (
        <div style={S.overlay} onClick={() => { setShowBook(false); setSel(new Set()); }}>
          <div style={S.modal} onClick={e => e.stopPropagation()}>
            <div style={S.mTitle}>🎸 Reservar Turno</div>
            <div style={S.mInfo}>{selLabel()}</div>
            <div style={S.mPrice}>{priceStr()}</div>
            <input style={S.inp} placeholder="Nombre de la banda o artista" value={bandName} autoFocus
              onChange={e => setBandName(e.target.value)} onKeyDown={e => e.key==='Enter' && confirmBook()} />
            <div style={S.mBtns}>
              <button style={S.btnCancel} onClick={() => { setShowBook(false); setSel(new Set()); }}>Cancelar</button>
              <button style={{...S.btnOk,...(!bandName.trim()?{opacity:.4,cursor:'not-allowed'}:{})}} onClick={confirmBook} disabled={!bandName.trim()}>Confirmar</button>
            </div>
          </div>
        </div>
      )}

      {/* Admin PIN modal */}
      {showAdmin && (
        <div style={S.overlay} onClick={() => { setShowAdmin(false); setPin(""); setPinErr(false); }}>
          <div style={S.modal} onClick={e => e.stopPropagation()}>
            <div style={S.mTitle}>🔐 Acceso Admin</div>
            <div style={S.mInfo}>Solo la dueña puede eliminar turnos</div>
            <input style={{...S.inp,marginTop:12}} type="password" inputMode="numeric" placeholder="PIN"
              value={pin} autoFocus onChange={e => { setPin(e.target.value); setPinErr(false); }} onKeyDown={e => e.key==='Enter' && loginAdmin()} />
            {pinErr && <div style={{color:'#FF7070',fontSize:11,letterSpacing:2,marginTop:-8,marginBottom:8}}>PIN incorrecto</div>}
            <div style={S.mBtns}>
              <button style={S.btnCancel} onClick={() => { setShowAdmin(false); setPin(""); setPinErr(false); }}>Cancelar</button>
              <button style={S.btnOk} onClick={loginAdmin}>Entrar</button>
            </div>
          </div>
        </div>
      )}

      {/* Delete confirm modal */}
      {showDel && (
        <div style={S.overlay} onClick={() => setShowDel(false)}>
          <div style={S.modal} onClick={e => e.stopPropagation()}>
            <div style={S.mTitle}>🗑 Eliminar turno</div>
            {delKey && (() => {
              const [ds, hs] = delKey.split('_'); const h = parseInt(hs);
              const d = new Date(ds+'T00:00:00');
              return <div style={S.mInfo}>{DAYS_ES[dayIdx(d)]} {d.getDate()} {MONTHS_ES[d.getMonth()]} · {h}:00 – {h+1}:00<br/><strong style={{color:'#C9B88A'}}>{bookings[delKey]?.name}</strong></div>;
            })()}
            <div style={{color:'#FF9090',fontSize:10,letterSpacing:1,marginTop:8,marginBottom:16}}>Esta acción no se puede deshacer.</div>
            <div style={S.mBtns}>
              <button style={S.btnCancel} onClick={() => setShowDel(false)}>Cancelar</button>
              <button style={{...S.btnOk,background:'rgba(255,60,60,.15)',border:'1px solid rgba(255,60,60,.5)',color:'#FF8080'}} onClick={confirmDel}>Eliminar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  root:{minHeight:'100vh',background:'#080808',color:'#F0EDE5',fontFamily:"'Oswald','Arial Narrow',sans-serif",position:'relative',overflowX:'hidden',userSelect:'none',WebkitUserSelect:'none',touchAction:'pan-y'},
  bgWrap:{position:'fixed',inset:0,zIndex:0,overflow:'hidden'},
  bgInner:{position:'absolute',top:0,bottom:0,left:'-80px',right:'-80px'},
  bgImg:{width:'100%',height:'100%',objectFit:'cover',objectPosition:'center',display:'block'},
  bgOverlay:{position:'absolute',inset:0,background:'linear-gradient(180deg,rgba(8,8,8,.88) 0%,rgba(8,8,8,.76) 35%,rgba(8,8,8,.9) 100%)'},
  header:{position:'sticky',top:0,zIndex:20,background:'rgba(8,8,8,.92)',backdropFilter:'blur(12px)',borderBottom:'1px solid rgba(201,184,138,.18)',padding:'10px 16px',display:'flex',alignItems:'center',justifyContent:'space-between'},
  logoText:{fontSize:18,fontWeight:700,letterSpacing:5,color:'#F5F1E8'},
  logoSub:{fontSize:9,letterSpacing:3,color:'#666',textTransform:'uppercase',marginTop:2},
  adminBtn:{background:'transparent',border:'1px solid rgba(255,255,255,.12)',color:'#777',padding:'6px 12px',borderRadius:4,cursor:'pointer',fontSize:14,letterSpacing:1},
  adminOn:{border:'1px solid rgba(201,184,138,.4)',color:'#C9B88A',background:'rgba(201,184,138,.08)'},
  weekNav:{position:'sticky',top:55,zIndex:15,background:'rgba(8,8,8,.88)',backdropFilter:'blur(8px)',borderBottom:'1px solid rgba(255,255,255,.05)',display:'flex',alignItems:'center',justifyContent:'space-between',padding:'7px 16px'},
  navBtn:{background:'transparent',border:'1px solid rgba(255,255,255,.15)',color:'#C9B88A',padding:'4px 14px',borderRadius:4,cursor:'pointer',fontSize:20,lineHeight:1,fontFamily:'inherit'},
  weekLabel:{fontSize:11,letterSpacing:2,color:'#888',textTransform:'uppercase',textAlign:'center',flex:1,padding:'0 8px'},
  adminBanner:{position:'sticky',top:100,zIndex:14,background:'rgba(255,80,80,.12)',color:'#FF9090',textAlign:'center',padding:'5px',fontSize:9,letterSpacing:4,textTransform:'uppercase',borderBottom:'1px solid rgba(255,80,80,.25)'},
  gridWrap:{position:'relative',zIndex:10,overflowX:'auto',paddingBottom:80,WebkitOverflowScrolling:'touch'},
  grid:{display:'grid',gap:1,background:'rgba(255,255,255,.04)'},
  thEmpty:{height:52,background:'rgba(8,8,8,.75)'},
  th:{height:52,background:'rgba(8,8,8,.75)',display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',gap:2,borderBottom:'2px solid rgba(255,255,255,.07)',position:'relative'},
  thToday:{borderBottomColor:'rgba(201,184,138,.55)',background:'rgba(201,184,138,.05)'},
  thDay:{fontSize:9,letterSpacing:2,color:'#666',textTransform:'uppercase'},
  thNum:{fontSize:20,fontWeight:600,color:'#F0EDE5',lineHeight:1},
  todayDot:{width:4,height:4,borderRadius:'50%',background:'#C9B88A',position:'absolute',bottom:4,left:'50%',transform:'translateX(-50%)'},
  timeCell:{display:'flex',alignItems:'center',justifyContent:'flex-end',paddingRight:7,fontFamily:"'Share Tech Mono',monospace",fontSize:9,color:'#444',letterSpacing:1,height:46,background:'rgba(8,8,8,.65)',borderRight:'1px solid rgba(255,255,255,.05)'},
  cell:{height:46,position:'relative',cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',borderBottom:'1px solid rgba(255,255,255,.035)',borderLeft:'1px solid transparent',transition:'background .1s'},
  cellFree:{background:'rgba(255,255,255,.018)'},
  cellPast:{background:'rgba(0,0,0,.3)',cursor:'default',opacity:.35},
  cellBooked:{background:'rgba(201,184,138,.1)',cursor:'default',borderLeftColor:'rgba(201,184,138,.35)',borderLeftWidth:2},
  cellSel:{background:'rgba(80,160,255,.18)',borderLeftColor:'rgba(80,160,255,.5)',borderLeftWidth:2},
  cellTxt:{fontSize:9,letterSpacing:.5,color:'#C9B88A',textAlign:'center',padding:'0 4px',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap',width:'100%',pointerEvents:'none'},
  selDot:{width:6,height:6,borderRadius:'50%',background:'rgba(80,160,255,.7)',pointerEvents:'none'},
  selBar:{position:'fixed',bottom:0,left:0,right:0,zIndex:30,background:'rgba(8,8,8,.96)',backdropFilter:'blur(14px)',borderTop:'1px solid rgba(201,184,138,.28)',padding:'12px 16px',display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'},
  selLabelTxt:{fontSize:11,letterSpacing:1,color:'#ADADAD'},
  selPriceTxt:{fontSize:14,color:'#C9B88A',letterSpacing:1,fontWeight:600,marginTop:2},
  btnReservar:{background:'rgba(201,184,138,.13)',border:'1px solid rgba(201,184,138,.45)',color:'#C9B88A',padding:'9px 16px',borderRadius:4,cursor:'pointer',fontSize:11,letterSpacing:3,fontFamily:'inherit',textTransform:'uppercase'},
  btnClear:{background:'transparent',border:'1px solid rgba(255,255,255,.12)',color:'#555',padding:'9px 11px',borderRadius:4,cursor:'pointer',fontSize:14},
  overlay:{position:'fixed',inset:0,background:'rgba(0,0,0,.82)',zIndex:50,display:'flex',alignItems:'center',justifyContent:'center',padding:16},
  modal:{background:'#101010',border:'1px solid rgba(201,184,138,.28)',borderRadius:8,padding:'28px 24px',width:'100%',maxWidth:380,boxShadow:'0 24px 60px rgba(0,0,0,.85)'},
  mTitle:{fontSize:15,letterSpacing:4,color:'#F0EDE5',marginBottom:10,textTransform:'uppercase'},
  mInfo:{fontSize:12,color:'#ADADAD',letterSpacing:1,lineHeight:1.7,marginBottom:4},
  mPrice:{fontSize:18,color:'#C9B88A',letterSpacing:2,fontWeight:600,marginBottom:16},
  inp:{width:'100%',background:'rgba(255,255,255,.06)',border:'1px solid rgba(255,255,255,.14)',borderRadius:4,padding:'10px 12px',color:'#F0EDE5',fontSize:14,letterSpacing:1,outline:'none',boxSizing:'border-box',fontFamily:'inherit',marginBottom:16},
  mBtns:{display:'flex',gap:8,justifyContent:'flex-end'},
  btnCancel:{background:'transparent',border:'1px solid rgba(255,255,255,.13)',color:'#666',padding:'8px 16px',borderRadius:4,cursor:'pointer',fontSize:11,letterSpacing:2,fontFamily:'inherit',textTransform:'uppercase'},
  btnOk:{background:'rgba(201,184,138,.13)',border:'1px solid rgba(201,184,138,.45)',color:'#C9B88A',padding:'8px 16px',borderRadius:4,cursor:'pointer',fontSize:11,letterSpacing:2,fontFamily:'inherit',textTransform:'uppercase'},
  loader:{position:'relative',zIndex:10,textAlign:'center',padding:'60px 16px',color:'#ADADAD',fontSize:13,letterSpacing:2,lineHeight:2},
};
